  function updateQuote() {
    if (!quoteSection) return;
    const rect = quoteSection.getBoundingClientRect();
    const vh = window.innerHeight;

    // Symmetric bell-curve proximity:
    //   1 when section is perfectly centered in viewport
    //   0 when section is fully above or below the viewport
    // This makes the reveal SCRUB IN as the section enters, peak when centered,
    // and SCRUB OUT as it exits — every frame is a continuous interpolation.
    const sectionCenter = rect.top + rect.height / 2;
    const viewportCenter = vh / 2;
    const offset = Math.abs(sectionCenter - viewportCenter);
    const halfRange = (rect.height + vh) / 2;
    const proximity = clamp01(1 - offset / halfRange);

    // Smoothstep gives a gentle ease-in/out at the proximity extremes
    // (slow start near edges, faster through middle, slow ease into peak).
    const t = smoothstep(proximity);

    // Each element has a slight bias: small things (kicker, rules) reach 1 a bit
    // before the headline, so the composition "sets" naturally even though
    // everything is driven by the same proximity scrub.
    const tEarly  = smoothstep(clamp01((proximity - 0.05) / 0.85));
    const tMid    = smoothstep(clamp01((proximity - 0.10) / 0.85));
    const tLate   = smoothstep(clamp01((proximity - 0.15) / 0.80));

    // Kicker
    if (quoteKicker) quoteKicker.style.opacity = lerp(0, 0.95, tEarly).toFixed(3);

    // Top rule — expands 0 → 48px
    if (quoteRuleTop) quoteRuleTop.style.width = `${lerp(0, 48, tEarly).toFixed(1)}px`;
    // Byline
    if (quoteAuthor) quoteAuthor.style.opacity = lerp(0, 0.95, t).toFixed(3);
  }
  window.addEventListener('scroll', updateQuote, { passive: true });
  window.addEventListener('resize', updateQuote);
  updateQuote();
  // Debug-only: ?preview=quote forces the quote to its final formed state
  if (location.search.includes('preview=quote')) {
    setTimeout(() => {
      if (quoteSection) window.scrollTo(0, quoteSection.offsetTop + window.innerHeight * 0.4);
      if (quoteKicker) quoteKicker.style.opacity = '0.95';
      if (quoteRuleTop) quoteRuleTop.style.width = '48px';
      if (quoteRuleBottom) quoteRuleBottom.style.width = '48px';
      if (quoteJp) { quoteJp.style.opacity = '1'; quoteJp.style.transform = 'translateY(0) scale(1.06)'; quoteJp.style.letterSpacing = '0.58em'; }
      if (quoteText) { quoteText.style.opacity = '1'; quoteText.style.transform = 'translateY(0) scale(1.04)'; quoteText.style.filter = 'blur(0)'; quoteText.style.letterSpacing = '0.12em'; }
      if (quoteAuthor) quoteAuthor.style.opacity = '0.95';
    }, 200);
  }

  // Word-by-word scrubbing reveal for THE HOUSE lede
  const lede = document.getElementById('house-lede');
  if (lede) {
    const words = Array.from(lede.querySelectorAll('.word'));
    function updateLede() {
      const rect = lede.getBoundingClientRect();
      const vh = window.innerHeight;
      // 0 = top hits bottom of viewport; 1 = bottom hits top of viewport
      const progress = Math.max(0, Math.min(1, 1 - (rect.top - vh * 0.15) / (vh * 0.65)));
      const lit = Math.floor(progress * words.length);
      words.forEach((w, i) => { w.classList.toggle('lit', i <= lit); });
    }
    window.addEventListener('scroll', updateLede, { passive: true });
    window.addEventListener('resize', updateLede);
    updateLede();
  }

  // Standard reveals
  const io = new IntersectionObserver(es => {
    es.forEach(e => { if (e.isIntersecting) { e.target.classList.add('in'); io.unobserve(e.target); } });
  }, { threshold: 0.1 });
  document.querySelectorAll('article, figure, h2, h3').forEach(el => { el.classList.add('reveal'); io.observe(el); });
</script>
</body>
</html>
